def physical(sample): # Construct an exact differentiable full-order physical residual for one immutable case.
    data=np.load(RUN/'cases'/sample['id']/'fields.npz');matrix=load_npz(RUN/'cases'/sample['id']/'stiffness.npz').tocoo();indices=torch.tensor(np.vstack([matrix.row,matrix.col]),dtype=torch.int64);K=torch.sparse_coo_tensor(indices,torch.tensor(matrix.data,dtype=torch.float64),matrix.shape).coalesce();force=torch.tensor(data['f'].ravel(),dtype=torch.float64);free=torch.tensor(data['free'],dtype=torch.int64) # Retain every stiffness entry and free degree with double-precision multiplication.
