    scale=max(float(np.mean(calibration)),1e-20);weight=.1;optimizer=torch.optim.AdamW(model.parameters(),lr=2e-5,weight_decay=1e-6);baseline=validate(model,validation);baseline['composite']=baseline['data_relative_mse']+weight*baseline['raw_equilibrium_relative_mse']/scale;best_score=baseline['composite'];best=copy.deepcopy(model.state_dict());best_epoch=-1;history=[{'epoch':-1,'validation':baseline}];updates=0 # Fix relative physics weight and include the original model as a legitimate validation candidate.
