    model.load_state_dict(best);model.eval();torch.save({'state_dict':best,'features_size':checkpoint['features_size'],'selected_epoch':best_epoch,'training_ids':[s['id'] for s in train],'validation_ids':[s['id'] for s in validation],'source_checkpoint_sha256':sha(source),'loss_weight':weight,'training_only_raw_residual_normalizer':scale},directory/'model.pt');write_json(directory/'history.json',{'history':history,'epochs':4,'updates':updates,'selected_epoch':best_epoch,'best_validation_composite':best_score,'seconds':time.time()-started,'source_checkpoint_sha256':sha(source),'physics_loss':'full double-precision sparse Ku-f on every free degree; squared norm divided by physical force norm; normalized with frozen training-only starting magnitude','physics_weight':weight,'raw_residual_normalizer':scale,'selection_rule':'minimum validation displacement relative MSE + 0.1 times training-normalized raw equilibrium MSE; original model is candidate epoch -1'}) # Preserve real physical-loss training evidence even when original weights remain best.
