    summary=[{'family':family,'test_cases':8,'mean_relative_L2':float(np.mean([r['relative_L2'] for r in rows if r['family']==family and r['split']=='test'])),'max_full_equilibrium_relative':float(max(r['full_equilibrium_relative'] for r in rows if r['family']==family and r['split']=='test')),'accepted':sum(r['research_gate_pass'] for r in rows if r['family']==family and r['split']=='test')} for family in FAMILIES];write_json(directory/'evaluation.json',{'summary':summary,'cases':rows,'selected_epoch':best_epoch,'release':'HOLD unless all physical, accuracy and fidelity gates pass','physical_loss':'full raw Ku-f, all free DOFs, no projection, no numerical post-correction'});print('PHYSICS_COMPLETE',summary,flush=True) # Distinguish implemented physical training from achieved engineering qualification.
